import fs from "node:fs";
import path from "node:path";

// This app ships text courses. Speech is generated by the user and stored on their device.
const roots = process.argv.slice(2);
if (!roots.length) roots.push("public");
const forbidden = [];
for (const root of roots) {
  if (!fs.existsSync(root)) continue;
  for (const file of fs.readdirSync(root, {
    recursive: true,
    withFileTypes: true,
  })) {
    if (!file.isFile()) continue;
    const full = path.join(file.parentPath, file.name);
    if (
      /\.(wav|mp3|m4a|ogg|aac|flac|opus)$/i.test(file.name) ||
      path.relative(root, full).split(path.sep).includes("course-audio")
    )
      forbidden.push(full);
  }
}
if (forbidden.length) {
  console.error(
    "APK assets must not include pre-generated audio:\n" + forbidden.join("\n"),
  );
  process.exitCode = 1;
} else
  console.log("Audio packaging check passed: no pre-generated course audio.");
